-- RubberFlow รอบที่ 2 (20261108010000_rubberflow_shopfloor.sql): ล็อตวัตถุดิบ ใบเบิก (FEFO จ่ายทันที; ใบเก่าที่ค้างชั่งยังชั่ง/จ่ายทั้งใบได้) ล็อตผลิต 4 สถานี ใบส่งมอบ + ป้อนผลผลิตกลับ BOM ต่อใบส่งมอบ
-- กล่อง FG ผลตรวจ QC NCR แม่พิมพ์ · ตรวจทั้งฝั่งอนุญาตและปฏิเสธต่อบทบาท (ST / SR / WH / QA / สมาชิก RB / หัว RB / กลุ่มวางแผน) ชนรายระเบียนก่อนสิทธิ์ audit และล้างข้อมูลทดสอบ
-- (authenticated อ่านตาราง rf_* ตรงไม่ได้ จึงนับตารางด้วย reset role เสมอ) ส่วนที่ไม่เปลี่ยนจากรอบที่ 1 ตรวจใน rubberflow_core.test.sql
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();

-- 1. โครงสร้างและสิทธิ์ ------------------------------------------------------------
create temp table rf2_tables(name text) on commit drop;
insert into rf2_tables values ('rf_molds'), ('rf_material_lots'), ('rf_requisitions'), ('rf_lots'), ('rf_transfers'), ('rf_fg_boxes'), ('rf_qc_records'), ('rf_ncrs');

select is((select count(*) from rf2_tables t join pg_class c on c.oid = ('public.' || t.name)::regclass where c.relrowsecurity),
  8::bigint, 'every new RubberFlow table has RLS enabled');
select ok(not exists (
    select 1 from rf2_tables t, unnest(array['anon', 'authenticated']) r(role), unnest(array['select', 'insert', 'update', 'delete']) p(priv)
    where has_table_privilege(r.role, 'public.' || t.name, p.priv)),
  'anon and authenticated have no direct table privilege on any new RubberFlow table');
select ok(not exists (
    select 1 from rf2_tables t
    where not exists (select 1 from pg_policy p where p.polrelid = ('public.' || t.name)::regclass and p.polname = t.name || '_no_direct_access')),
  'every new table has the deny-all policy');
select ok(not exists (
    select 1 from rf2_tables t
    where not exists (select 1 from pg_policy p where p.polrelid = ('public.' || t.name)::regclass
                      and p.polname = 'lab_only_no_access' and not p.polpermissive)),
  'every new table has the restrictive lab_only_no_access policy');
select ok(not exists (
    select 1 from rf2_tables t
    where not exists (select 1 from pg_trigger g where g.tgrelid = ('public.' || t.name)::regclass and g.tgname = t.name || '_sandbox_scope' and not g.tgisinternal)
       or not exists (select 1 from pg_trigger g where g.tgrelid = ('public.' || t.name)::regclass and g.tgname = t.name || '_stamp_version' and not g.tgisinternal)),
  'every new table separates test data from real data and stamps changed_version by trigger');
select ok(not exists (select 1 from rf2_tables t where not (t.name = any (private.sandbox_unguarded_tables()))),
  'the new tables are registered as sandbox aware');
select ok('rf_orders' = any (private.sandbox_unguarded_tables()) and 'bom_jobs' = any (private.sandbox_unguarded_tables()) and 'ncr_reports' = any (private.sandbox_unguarded_tables()),
  'the redefined sandbox list keeps the earlier RubberFlow, BOM and NCR tables');
select is((select count(*) from pg_indexes where schemaname = 'public' and indexname in ('rf_molds_changed_idx', 'rf_material_lots_changed_idx', 'rf_requisitions_changed_idx',
  'rf_lots_changed_idx', 'rf_transfers_changed_idx', 'rf_fg_boxes_changed_idx', 'rf_qc_records_changed_idx', 'rf_ncrs_changed_idx')), 8::bigint,
  'the new tables are indexed by (is_test, changed_version)');
select ok(not exists (
    select 1 from pg_constraint c
    where c.contype = 'f' and c.conrelid in ('public.rf_requisitions'::regclass, 'public.rf_lots'::regclass, 'public.rf_transfers'::regclass,
                                             'public.rf_fg_boxes'::regclass, 'public.rf_qc_records'::regclass, 'public.rf_material_lots'::regclass)
      and (select r.relname from pg_class r where r.oid = c.confrelid) like 'rf\_%'
      and pg_get_constraintdef(c.oid) not like '%, is_test) REFERENCES %'),
  'every foreign key of the new tables is paired with is_test');
select ok(not exists (select 1 from pg_constraint c where c.conrelid in ('public.rf_requisitions'::regclass, 'public.rf_lots'::regclass, 'public.rf_transfers'::regclass,
  'public.rf_orders'::regclass) and c.contype = 'f' and pg_get_constraintdef(c.oid) like '%bom_%'), 'no RubberFlow table has a foreign key into BOM');
select ok(not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'rf_orders' and column_name = 'fed_back_at'),
  'the retired feedback marker column is gone');
select ok(not exists (
    select 1 from unnest(array['public.app_rf_master()', 'public.app_rf_master_since(bigint)', 'public.app_rf_save(jsonb,bigint,text,jsonb,text)',
                               'public.app_rf_audit(integer)', 'public.app_sandbox_purge_rf()']) f(sig)
    where has_function_privilege('anon', f.sig, 'execute') or not has_function_privilege('authenticated', f.sig, 'execute')),
  'the public RubberFlow RPCs keep their grants (signed-in users only)');
select ok((select bool_and(p.prosecdef and p.proconfig @> array['search_path=""']) from pg_proc p
           where p.oid in ('public.app_rf_save(jsonb,bigint,text,jsonb,text)'::regprocedure, 'public.app_sandbox_purge_rf()'::regprocedure)),
  'the replaced RPCs are still security definer with an empty search_path');
select is((select count(*)::integer from private.lab_only_unguarded_functions()), 0, 'every callable public function keeps the lab-only guard');
select ok(not exists (
    select 1 from pg_proc p
    where p.pronamespace = 'private'::regnamespace and p.proname like 'rf\_%'
      and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))),
  'clients cannot call any private RubberFlow helper (the new writers included)');
select ok(exists (select 1 from pg_proc p where p.pronamespace = 'private'::regnamespace and p.proname = 'rf_apply_feedback' and p.pronargs = 3)
      and not exists (select 1 from pg_proc p where p.pronamespace = 'private'::regnamespace and p.proname = 'rf_apply_feedback' and p.pronargs = 2),
  'the feedback function now takes the transfer (the old order-only signature is gone)');
select ok(pg_get_functiondef('private.rf_save_requisitions(uuid,text,boolean,text,jsonb,bigint,bigint)'::regprocedure) like '%trunc(least(v_free, v_left), 4)%'
      and pg_get_functiondef('private.rf_save_requisitions(uuid,text,boolean,text,jsonb,bigint,bigint)'::regprocedure) not like '%greatest(0, trim_scale(round(v_lot.qty_kg - v_target%'
      and pg_get_functiondef('private.rf_save_requisitions(uuid,text,boolean,text,jsonb,bigint,bigint)'::regprocedure) like '%if v_after < 0 then raise exception ''RF_INSUFFICIENT_STOCK''%',
  'a new requisition allocates truncated kilos (never above a lot) and stops instead of clamping a lot to zero');
select ok(array['receiveMaterial', 'setMaterialLotStatus', 'createRequisition', 'weighLine', 'issueRequisition', 'endRest', 'createTransfer', 'receiveTransfer', 'shipBoxes',
                'createNcr', 'updateNcr', 'closeNcr', 'cleanMold', 'saveMold', 'recordMixing', 'recordExtrusion', 'recordCuring', 'recordFinishing', 'addQcRecord']
          <@ private.rf_client_actions(), 'the action whitelist knows every shop-floor action');

-- 2. บัญชีทดสอบและแถวจริงที่ต้องไม่ถูกแตะ ---------------------------------------------------------
insert into auth.users (id, email, raw_user_meta_data) values ('8f100000-0000-0000-0000-000000000001', 'rf2-admin@test.local', '{}');
insert into public.employees (id, employee_no, first_name, last_name, email, job_title, department_id, role_id, auth_user_id) values
  ('8f100000-0000-0000-0000-000000000101', 'RF2-ADMIN', 'Rf', 'Admin', 'rf2-admin@test.local', 'System Administrator',
   (select id from public.departments where code = 'MGT'), (select id from public.roles where code = 'admin'), '8f100000-0000-0000-0000-000000000001');
select count(set_config('test.p_' || lower(replace(employee_no, '-', '_')), id::text, true)) from public.employees where is_test;
select count(set_config('test.n_' || lower(replace(employee_no, '-', '_')), first_name || ' ' || last_name, true)) from public.employees where is_test;
-- ข้อมูลจริง (ไม่ใช่โหมดทดสอบ) ใส่ตรง: โหมดทดสอบต้องมองไม่เห็นและ purge ไม่แตะ
insert into public.rf_materials (code, name) values ('REAL-MAT', 'วัตถุดิบจริง');
insert into public.rf_material_lots (lot_no, material_code, qty_kg, initial_kg, expiry) values ('REAL-LOT', 'REAL-MAT', 10, 10, 1900000000000);
insert into public.rf_molds (mold_no, name, clean_every) values ('REAL-DIE', 'หัวดายจริง', 1000);
select is((select count(*) from public.rf_material_lots where not is_test) + (select count(*) from public.rf_molds where not is_test), 2::bigint, 'the real stock lot and mold were inserted as real (non-test) rows');
select set_config('test.now_ms', (extract(epoch from now()) * 1000)::bigint::text, true);
select set_config('request.jwt.claims', '{"sub":"8f100000-0000-0000-0000-000000000001","role":"authenticated"}', true);
set local role authenticated;
select throws_ok('select count(*) from public.rf_lots', '42501', null, 'clients cannot read the production lot table directly');
select throws_ok($$ insert into public.rf_fg_boxes (box_no, lot_no, order_no, recipe_code, qty, uom) values ('X', 'X', 'X', 'X', 1, 'm') $$, '42501', null, 'clients cannot write the box table directly');

-- 3. ข้อมูลตั้งต้น: วัตถุดิบ สูตร ใบสั่งผลิต (ผูกงาน BOM) ------------------------------------------
select public.app_sandbox_enter(current_setting('test.p_sbx_pp_staff')::uuid);
select set_config('test.mat', '{"code":"X","name":"x","category":"วัตถุดิบ","storage":"A-1","uom":"kg","active":true}', true);
select set_config('test.rec', '{"id":"RC-1","revision":1,"productCode":"P-1","uom":"m","batchKg":60,"stages":[{"stage":1,"mixerTemp":80,"dumpTemp":115,"mixMin":3},{"stage":2,"mixerTemp":90,"dumpTemp":140,"mixMin":2}],"dumpTol":6,"restHours":4,"yieldPerKg":6.1,"items":[{"materialCode":"MAT-A","phr":100,"stage":1},{"materialCode":"MAT-B","phr":50,"stage":1},{"materialCode":"MAT-C","phr":10,"stage":2}],"status":"draft"}', true);
select set_config('test.wo', '{"id":"WO-S1","customer":"ACME","customerPo":"PO-1","recipeId":"RC-1","recipeRevision":1,"color":"ดำ","targetQty":140,"targetKg":17.5,"kgPerUnit":0.125,"producedQty":0,"startDate":1762387200000,"dueDate":1765065600000,"priority":"normal","note":"","status":"planned"}', true);
select set_config('test.ord', '{"id":"X","customer":"ACME","country":"TH","orderType":"SA","orderedAt":1762387200000,"whDue":1765065600000,"due":{"RB":1763000000000,"PK":1764000000000},"dueDefaults":["RB"],"revision":0,"status":"draft","items":[],"explosion":null,"explodedAt":null,"stockCounts":{},"note":""}', true);
select set_config('test.job', '{"id":"X","orderId":"X","dept":"RB","itemCode":"RB-A","name":"งานทดสอบ","kind":"RB","uom":"pcs","qtyPlanned":1000,"qtyRequired":1000,"stockCounted":null,"qtyDone":0,"qtyReject":0,"dueAt":1764201600000,"status":"queued","externalRef":null,"fgCodes":["FG-A"],"reports":[]}', true);
select set_config('test.expl', '[{"itemCode":"FG-A","level":0,"fgQty":10,"required":10},{"itemCode":"SE-A","level":1,"fgQty":10,"required":20},{"itemCode":"RB-A","level":2,"fgQty":10,"required":40}]', true);
select public.app_rf_save(jsonb_build_object('materials', jsonb_build_object('upsert', jsonb_build_array(
  current_setting('test.mat')::jsonb || '{"code":"MAT-A","name":"ยาง EPDM"}'::jsonb, current_setting('test.mat')::jsonb || '{"code":"MAT-B","name":"เขม่าดำ"}'::jsonb,
  current_setting('test.mat')::jsonb || '{"code":"MAT-C","name":"สารตัวเร่ง"}'::jsonb))), 0, 'saveMaterial');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select public.app_rf_save(jsonb_build_object('recipes', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.rec')::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createRecipe');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_mgr')::uuid);
select public.app_rf_save(jsonb_build_object('recipes', jsonb_build_object('upsert', jsonb_build_array(
  (select r || '{"status":"approved"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'recipes') r where r ->> 'id' = 'RC-1')))), (public.app_rf_master() ->> 'version')::bigint, 'approveRecipe');
select is((select r ->> 'status' from jsonb_array_elements(public.app_rf_master() -> 'recipes') r where r ->> 'id' = 'RC-1'), 'approved', 'the RB head approved the two-stage recipe');

-- BOM: ใบ PI 25001 ปล่อยผลิตแล้ว มีงาน RB 1,000 ชิ้น (WO ผูกงานนี้เพื่อทดสอบการป้อนกลับต่อใบส่งมอบ)
select public.app_sandbox_enter(current_setting('test.p_sbx_pp_staff')::uuid);
select public.app_bom_save_master('{"items":{"upsert":[
  {"code":"FG-A","kind":"FG","name":"สินค้า A","ownerDept":"PK","uom":"set"},
  {"code":"SE-A","kind":"SE","name":"ชิ้นยาง A","ownerDept":"GR","uom":"pcs"},
  {"code":"RB-A","kind":"RB","name":"เส้นยาง A","ownerDept":"RB","uom":"pcs"},
  {"code":"P-1","kind":"PURCHASED","name":"กล่อง","ownerDept":"ST","uom":"box"}]}}'::jsonb, 0, 'importFlat');
select public.app_bom_save_master(jsonb_build_object('orders', jsonb_build_object('upsert', jsonb_build_array(
  current_setting('test.ord')::jsonb || jsonb_build_object('id', '251108-25001', 'items', '[{"fgCode":"FG-A","qty":10,"colorSet":"A","note":""}]'::jsonb, 'explosion', current_setting('test.expl')::jsonb)))),
  (public.app_bom_master() ->> 'version')::bigint, 'createOrder');
select public.app_bom_save_master(jsonb_build_object(
  'orders', jsonb_build_object('upsert', (select jsonb_agg(o || '{"status":"released"}'::jsonb) from jsonb_array_elements(public.app_bom_master() -> 'orders') o)),
  'jobs', jsonb_build_object('upsert', jsonb_build_array(
    current_setting('test.job')::jsonb || '{"id":"JOB-S1-RB","orderId":"251108-25001","dept":"RB","itemCode":"RB-A","kind":"RB"}'::jsonb,
    current_setting('test.job')::jsonb || '{"id":"JOB-S1-GR","orderId":"251108-25001","dept":"GR","itemCode":"SE-A","kind":"SE"}'::jsonb,
    current_setting('test.job')::jsonb || '{"id":"JOB-S1-PK","orderId":"251108-25001","dept":"PK","itemCode":"FG-A","kind":"FG","uom":"set"}'::jsonb))),
  (public.app_bom_master() ->> 'version')::bigint, 'releaseOrder');
select is((select count(*)::integer from jsonb_array_elements(public.app_bom_master() -> 'jobs')), 3, 'three jobs were created by the release');

select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select public.app_rf_save(jsonb_build_object('orders', jsonb_build_object('upsert', jsonb_build_array(
  current_setting('test.wo')::jsonb || '{"sourceJobId":"JOB-S1-RB"}'::jsonb, current_setting('test.wo')::jsonb || '{"id":"WO-S2","targetQty":50}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createOrder');
select is((select j -> 'externalRef' ->> 'woId' from jsonb_array_elements(public.app_bom_master() -> 'jobs') j where j ->> 'id' = 'JOB-S1-RB'), 'WO-S1', 'the work order is linked to the RB job');
select public.app_sandbox_enter(current_setting('test.p_sbx_pp_staff')::uuid);
select public.app_rf_save(jsonb_build_object('orders', jsonb_build_object('upsert', jsonb_build_array(
  (select w || '{"status":"released"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'orders') w where w ->> 'id' = 'WO-S1')))), (public.app_rf_master() ->> 'version')::bigint, 'setOrderStatus');
select is((select w ->> 'status' from jsonb_array_elements(public.app_rf_master() -> 'orders') w where w ->> 'id' = 'WO-S1'), 'released', 'the planner released the work order (WO-S2 stays planned)');
select is(public.app_rf_master() #>> '{materialLots,0}', null, 'the real stock lot is never listed');


-- 4. แม่พิมพ์ / หัวดาย -------------------------------------------------------------------
select set_config('test.mold', '{"id":"X","name":"x","kind":"die","unit":"m","perCycle":1,"cleanEvery":6000,"pmLimit":250000,"totalUsage":0,"usageSinceClean":0}', true);
select public.app_sandbox_enter(current_setting('test.p_sbx_st_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"หัวดาย"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_FORBIDDEN', 'ST staff cannot add a mold');
select public.app_sandbox_enter(current_setting('test.p_sbx_qa_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"หัวดาย"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_FORBIDDEN', 'QA staff cannot add a mold');
select public.app_sandbox_enter(current_setting('test.p_sbx_sr_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"หัวดาย"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_FORBIDDEN', 'SR staff cannot add a mold');
select public.app_sandbox_enter(current_setting('test.p_sbx_wh_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"หัวดาย"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_FORBIDDEN', 'WH staff cannot add a mold');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"bad id","name":"x"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_INVALID_MOLD', 'a mold code with a space is refused');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || jsonb_build_object('id', 'DIE-1', 'name', repeat('ก', 121))))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_INVALID_MOLD', 'a mold name is at most 120 characters (the lot machine column is 120)');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"x","kind":"press"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_INVALID_MOLD', 'an unknown mold kind is refused');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"x","cleanEvery":0}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_INVALID_MOLD', 'a zero cleaning interval is refused');
select set_config('test.res', (public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-1","name":"หัวดาย Door Seal","totalUsage":182400,"usageSinceClean":1200,"lastCleanAt":1}'::jsonb, current_setting('test.mold')::jsonb || '{"id":"MD-1","name":"แม่พิมพ์ 24 cavity","kind":"mold","unit":"shot","perCycle":24,"cleanEvery":1200,"pmLimit":60000}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold'))::text, true);
select is(jsonb_array_length(current_setting('test.res')::jsonb -> 'changes' -> 'molds' -> 'upsert'), '2', 'an RB member adds two molds in one call');
select is((select x ->> 'totalUsage' from jsonb_array_elements(current_setting('test.res')::jsonb -> 'changes' -> 'molds' -> 'upsert') x where x ->> 'id' = 'DIE-1'), '0', 'a new mold starts at zero total usage (the client value is ignored)');
select is((select x ->> 'usageSinceClean' from jsonb_array_elements(current_setting('test.res')::jsonb -> 'changes' -> 'molds' -> 'upsert') x where x ->> 'id' = 'DIE-1'), '0', 'and at zero usage since cleaning');
select is((select x ->> 'lastCleanAt' from jsonb_array_elements(current_setting('test.res')::jsonb -> 'changes' -> 'molds' -> 'upsert') x where x ->> 'id' = 'DIE-1'), current_setting('test.now_ms'), 'the last cleaning time of a new mold is the server time, not the client value');
select public.app_sandbox_enter(current_setting('test.p_sbx_pp_staff')::uuid);
select is(public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array((select x || '{"name":"หัวดาย Door Seal 18x2.5","pmLimit":300000}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'molds') x where x ->> 'id' = 'DIE-1')))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') -> 'changes' -> 'molds' -> 'upsert' -> 0 ->> 'name', 'หัวดาย Door Seal 18x2.5', 'a planner edits the mold master data');
select public.app_sandbox_enter(current_setting('test.p_sbx_st_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array((select x || '{"name":"ห้ามแก้"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'molds') x where x ->> 'id' = 'DIE-1')))), (public.app_rf_master() ->> 'version')::bigint, 'saveMold') $$, 'RF_FORBIDDEN', 'ST staff cannot edit a mold');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select set_config('test.v', (public.app_rf_master() ->> 'version')::text, true);
