select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select set_config('test.res', (public.app_rf_save(jsonb_build_object('requisitions', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.req')::jsonb || '{"id":"REQ-1","batches":1}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createRequisition'))::text, true);
select is(jsonb_array_length(current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines'), '3', 'the server exploded the recipe into three lines (the junk line from the client is gone)');
select is((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 0 ->> 'lotNo'), 'RM-A-1', 'FEFO: the lot that expires first is picked (the expired lot and the later lot are skipped)');
select is((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 0 ->> 'targetKg'), '37.5', 'MAT-A needs 100/160 of a 60 kg batch');
select is((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 1 ->> 'materialCode') || '/' || (current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 1 ->> 'lotNo') || '/' || (current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 1 ->> 'targetKg'), 'MAT-B/RM-B-1/18.75', 'MAT-B comes from its only lot');
select is((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 2 ->> 'stage'), '2', 'stage 2 materials come after stage 1 materials');
select is((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 2 ->> 'targetKg'), '3.75', 'MAT-C needs 10/160 of a batch');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 0 ->> 'actualKg', '37.5', 'the first line is issued at its target kilograms (no weighing)');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 0 ->> 'weighedBy', current_setting('test.n_sbx_rb_staff'), 'the line records who issued it');
select ok((current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 0 ->> 'weighedAt')::bigint >= current_setting('test.now_ms')::bigint, 'and the server time');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'requisitions' -> 'upsert' -> 0 -> 'lines' -> 1 ->> 'actualKg', '18.75', 'every line is issued at its target');
