select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.ncr')::jsonb || '{"id":"NCR-1","lotId":"bad lot"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createNcr') $$, 'RF_INVALID_NCR', 'a lot number with a space is refused');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.ncr')::jsonb || '{"id":"NCR-1","title":" "}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createNcr') $$, 'RF_INVALID_NCR', 'a blank title is refused');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.ncr')::jsonb || '{"id":"NCR-1","status":"closed"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createNcr') $$, 'RF_INVALID_TRANSITION', 'an NCR starts open');
select is((select x ->> 'qc' from jsonb_array_elements(public.app_rf_master() -> 'lots') x where x ->> 'id' = 'EX-1'), 'pass', 'the extrusion lot still passes before the NCR');
select set_config('test.res', (public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.ncr')::jsonb || '{"id":"NCR-1"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createNcr'))::text, true);
select is(jsonb_array_length(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 -> 'whys'), '2', 'blank why lines are dropped');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'createdBy', current_setting('test.n_sbx_qa_staff'), 'the opener is the persona');
select is((select x ->> 'qc' from jsonb_array_elements(public.app_rf_master() -> 'lots') x where x ->> 'id' = 'EX-1'), 'hold', 'opening an NCR puts the passing lot on hold');
select is((select x ->> 'holdReasons' from jsonb_array_elements(public.app_rf_master() -> 'lots') x where x ->> 'id' = 'EX-1')::jsonb ->> 0, 'เปิด NCR-1', 'with the NCR number as the reason');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select set_config('test.rbcopy', ((select x from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1'))::text, true);
select set_config('test.rbbase', (public.app_rf_master() ->> 'version')::text, true);
select public.app_sandbox_enter(current_setting('test.p_sbx_qa_staff')::uuid);
select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"whys":["ความหนาเกิน","ลากช้า","เซนเซอร์เพี้ยน"]}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.rbcopy')::jsonb || '{"corrective":"สอบเทียบเซนเซอร์"}'::jsonb))), current_setting('test.rbbase')::bigint, 'updateNcr') $$, 'RF_STALE', 'a stale copy of an NCR is stale (QA edited the why lines after the base version)');
select is(public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"corrective":"สอบเทียบเซนเซอร์"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'corrective', 'สอบเทียบเซนเซอร์', 'an RB member fills the corrective action');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"title":"แก้หัวข้อ"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') $$, 'RF_FORBIDDEN', 'an RB member cannot change the title');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"corrective":"x","owner":"คนอื่น"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') $$, 'RF_FORBIDDEN', 'an RB member cannot change the owner together with a field it may fill');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"status":"closed","preventive":"x"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'closeNcr') $$, 'RF_FORBIDDEN', 'an RB member cannot close an NCR');
select public.app_sandbox_enter(current_setting('test.p_sbx_qa_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"status":"closed","verification":"ตรวจแล้ว"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'closeNcr') $$, 'RF_INVALID_NCR', 'an NCR cannot be closed without a preventive action');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select is(public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"preventive":"เพิ่มรอบสอบเทียบใน PM"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'preventive', 'เพิ่มรอบสอบเทียบใน PM', 'an RB member fills the preventive action');
select public.app_sandbox_enter(current_setting('test.p_sbx_qa_staff')::uuid);
select set_config('test.res', (public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"status":"closed","verification":"ตรวจ 5 ล็อตถัดไปผ่าน"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'closeNcr'))::text, true);
select is(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'status', 'closed', 'QA closes the NCR');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'closedBy', current_setting('test.n_sbx_qa_staff'), 'the closer is the persona');
select ok(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ? 'closedAt', 'the close time is set by the server');
select is(current_setting('test.res')::jsonb -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'verification', 'ตรวจ 5 ล็อตถัดไปผ่าน', 'the verification is kept');
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"title":"แก้ทีหลัง"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') $$, 'RF_INVALID_TRANSITION', 'a closed NCR cannot be edited');
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select throws_ok($$ select public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array((select x || '{"corrective":"แก้ทีหลัง"}'::jsonb from jsonb_array_elements(public.app_rf_master() -> 'ncrs') x where x ->> 'id' = 'NCR-1')))), (public.app_rf_master() ->> 'version')::bigint, 'updateNcr') $$, 'RF_INVALID_TRANSITION', 'nor can an RB member fill a closed NCR');
select public.app_sandbox_enter(current_setting('test.p_sbx_pp_staff')::uuid);
select is(public.app_rf_save(jsonb_build_object('ncrs', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.ncr')::jsonb || '{"id":"NCR-2","lotId":"FN-3"}'::jsonb))), (public.app_rf_master() ->> 'version')::bigint, 'createNcr') -> 'changes' -> 'ncrs' -> 'upsert' -> 0 ->> 'id', 'NCR-2', 'a planner opens an NCR too');

-- 15. กฎป้อนกลับ BOM ตรวจตรงที่ฟังก์ชัน (ปรับสถานะงานด้วย superuser เพื่อสร้างสถานการณ์) ----------------------------------
reset role;
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '0', 'a job that is done takes no more feedback');
update public.bom_jobs set status = 'in_progress', qty_done = 0, done_at = null where is_test and job_no = 'JOB-S1-RB';
update public.rf_orders set kg_per_unit = null where is_test and wo_no = 'WO-S1';
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '0', 'a transfer in kg cannot be converted without kg per unit: nothing is written');
select is((select qty_done from public.bom_jobs where is_test and job_no = 'JOB-S1-RB'), 0::numeric, 'and the job total is untouched');
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-2'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '1', 'a transfer in the unit of the work order needs no conversion');
select is((select qty_done from public.bom_jobs where is_test and job_no = 'JOB-S1-RB'), 300::numeric, 'and adds its quantity');
update public.rf_orders set kg_per_unit = 0.125 where is_test and wo_no = 'WO-S1';
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '1', 'with kg per unit the kg transfer is converted (58 / 0.125 = 464)');
select is((select qty_done from public.bom_jobs where is_test and job_no = 'JOB-S1-RB'), 764::numeric, 'so the total is 300 + 464');
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S2')) ->> 'jobs', '0', 'a work order that is not linked to a job feeds nothing');
update public.bom_jobs set external_ref = jsonb_build_object('system', 'rubberflow', 'woId', 'WO-OTHER', 'kg', 0) where is_test and job_no = 'JOB-S1-RB';
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '0', 'a job linked to another work order takes nothing');
update public.bom_jobs set external_ref = jsonb_build_object('system', 'rubberflow', 'woId', 'WO-S1', 'kg', 0) where is_test and job_no = 'JOB-S1-RB';
update public.bom_orders set status = 'completed' where is_test and id = (select order_pk from public.bom_jobs where is_test and job_no = 'JOB-S1-RB');
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '0', 'a job of a completed PI takes nothing');
update public.bom_orders set status = 'released' where is_test and id = (select order_pk from public.bom_jobs where is_test and job_no = 'JOB-S1-RB');
select is(private.rf_apply_feedback('x', (select t from public.rf_transfers t where t.is_test and t.transfer_no = 'TR-1'), (select o from public.rf_orders o where o.is_test and o.wo_no = 'WO-S1')) ->> 'jobs', '1', 'a job of a released PI takes the feedback and the PI starts');
select is((select status from public.bom_orders where is_test and id = (select order_pk from public.bom_jobs where is_test and job_no = 'JOB-S1-RB')), 'in_progress', 'released -> in_progress');
update public.rf_master_state set version = version + 1 where is_test;
set local role authenticated;

-- 16. audit และ delta ------------------------------------------------------------------------------
select public.app_sandbox_enter(current_setting('test.p_sbx_rb_staff')::uuid);
select ok(exists (select 1 from jsonb_array_elements(public.app_rf_audit()) a where a ->> 'action' = 'receiveTransfer' and a ->> 'detail' = 'transfers +1' and a ->> 'user' = current_setting('test.n_sbx_sr_staff')), 'the history records a receipt by its action name and the persona');
select ok(exists (select 1 from jsonb_array_elements(public.app_rf_audit()) a where a ->> 'action' = 'createRequisition' and a ->> 'detail' = 'requisitions +1'), 'and a requisition');
select ok(exists (select 1 from jsonb_array_elements(public.app_rf_audit()) a where a ->> 'action' = 'weighLine' and a ->> 'detail' = 'requisitions +1'), 'and a weighing');
select ok(exists (select 1 from jsonb_array_elements(public.app_rf_audit()) a where a ->> 'action' = 'issueRequisition' and a ->> 'detail' = 'requisitions +1'), 'and an issue of a whole old requisition');
select is((select count(*) from jsonb_array_elements(public.app_bom_audit()) a where a ->> 'action' = 'rubberflow:receiveTransfer'), 3::bigint, 'the BOM history has one row per receipt that fed the job (three transfers)');
select is(public.app_rf_master_since(0) -> 'changes', (select jsonb_object_agg(l, jsonb_build_object('upsert', public.app_rf_master() -> l, 'delete', '[]'::jsonb)) from unnest(array['materials','recipes','orders','molds','materialLots','requisitions','lots','transfers','fgBoxes','qcRecords','ncrs','purchaseOrders']) l), 'the delta from version 0 equals the snapshot for all twelve lists');
select set_config('test.vb', (public.app_rf_master() ->> 'version')::text, true);
select set_config('test.res', public.app_rf_save(jsonb_build_object('molds', jsonb_build_object('upsert', jsonb_build_array(current_setting('test.mold')::jsonb || '{"id":"DIE-9","name":"หัวดายใหม่"}'::jsonb))), current_setting('test.vb')::bigint, 'saveMold')::text, true);
select is(current_setting('test.res')::jsonb -> 'changes', public.app_rf_master_since(current_setting('test.vb')::bigint) -> 'changes', 'the reply to a save equals the delta RPC from the same base');

-- 17. แยกโหมด และล้างข้อมูลทดสอบ ----------------------------------------------------------------------
reset role;
select ok((select bool_and(changed_version > 0) from public.rf_lots where is_test) and (select bool_and(changed_version > 0) from public.rf_transfers where is_test)
  and (select bool_and(changed_version > 0) from public.rf_fg_boxes where is_test) and (select bool_and(changed_version > 0) from public.rf_requisitions where is_test), 'every test row is stamped with the version that changed it');
select is((select count(*) from public.rf_material_lots where not is_test) + (select count(*) from public.rf_molds where not is_test), 2::bigint, 'the real stock lot and mold are untouched');
select ok((select count(*) from public.rf_lots where is_test) = 9 and (select count(*) from public.rf_fg_boxes where is_test) = 5 and (select count(*) from public.rf_transfers where is_test) = 4, 'the chain made nine lots, five boxes and four transfers');
select is((select max(changed_version) from public.rf_transfers where is_test) <= (select version from public.rf_master_state where is_test), true, 'no row is newer than the counter');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"8f100000-0000-0000-0000-000000000001","role":"authenticated"}', true);
select set_config('test.pre_version', public.app_rf_master() ->> 'version', true);
select set_config('test.pre_bom_version', public.app_bom_master() ->> 'version', true);
select set_config('test.purge', public.app_sandbox_purge_rf()::text, true);
select ok((current_setting('test.purge')::jsonb ->> 'deleted')::integer > 40, 'the purge reports the many rows it deleted');
select is(public.app_rf_master() - 'epoch', (select jsonb_build_object('version', current_setting('test.pre_version')::bigint) || jsonb_object_agg(l, '[]'::jsonb) from unnest(array['materials','recipes','orders','molds','materialLots','requisitions','lots','transfers','fgBoxes','qcRecords','ncrs','purchaseOrders']) l), 'all twelve lists are empty again and the counter keeps its value');
select is(public.app_bom_master() ->> 'version', current_setting('test.pre_bom_version'), 'the purge did not touch BOM');
reset role;
select is((select count(*) from public.rf_molds where is_test) + (select count(*) from public.rf_material_lots where is_test) + (select count(*) from public.rf_requisitions where is_test)
  + (select count(*) from public.rf_lots where is_test) + (select count(*) from public.rf_transfers where is_test) + (select count(*) from public.rf_fg_boxes where is_test)
  + (select count(*) from public.rf_qc_records where is_test) + (select count(*) from public.rf_ncrs where is_test), 0::bigint, 'no test row is left in any new table');
select is((select count(*) from public.rf_material_lots where not is_test) + (select count(*) from public.rf_molds where not is_test), 2::bigint, 'the real stock lot and mold survive the purge');

select * from finish();
rollback;
